"use client";

import { useState, useEffect } from "react";

export default function Lab5() {
  const [message, setMessage] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string>("");

  const fetchFromNodeServer = async () => {
    setLoading(true);
    setError("");
    setMessage("");
    
    try {
      const response = await fetch("http://localhost:4000/lab5/welcome");
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const text = await response.text();
      setMessage(text);
    } catch (err) {
      setError(`Error: ${err instanceof Error ? err.message : "Unknown error"}`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchFromNodeServer();
  }, []);

  return (
    <div id="wd-lab5">
      <h3>Lab 5: Node HTTP Server Testing</h3>
      <p>This lab tests the Node HTTP server at localhost:4000</p>
      
      <button 
        onClick={fetchFromNodeServer} 
        className="btn btn-primary"
        disabled={loading}
      >
        {loading ? "Fetching..." : "Fetch from Node Server"}
      </button>

      <div className="mt-3">
        {loading && <p className="text-info">Loading...</p>}
        
        {error && (
          <div className="alert alert-danger" role="alert">
            {error}
          </div>
        )}
        
        {message && (
          <div className="alert alert-success" role="alert">
            Server Response: <strong>{message}</strong>
          </div>
        )}
      </div>

      <hr />
      
      <h4>Expected Response:</h4>
      <p>When successfully connected to the Node server, you should see:</p>
      <code>Welcome to Lab 5</code>
    </div>
  );
}
